{
  "type": "object",
  "required": [
    "register_number",
    "company_name",
    "name",
    "mcc_code",
    "city",
    "district",
    "address",
    "phone",
    "email"
  ],
  "properties": {
    "owner_first_name": {
      "type": "string",
      "maxLength": 255,
      "description": "Эзэмшигчийн нэр"
    },
    "owner_last_name": {
      "type": "string",
      "maxLength": 255,
      "description": "Эзэмшигчийн овог"
    },
    "owner_register_no": {
      "type": "string",
      "maxLength": 255,
      "description": "Эзэмшигчийн регистрийн дугаар",
      "example": "УЗ96021105"
    },
    "register_number": {
      "type": "string",
      "maxLength": 255,
      "description": "Байгууллагын регистрийн дугаар",
      "example": "6691374"
    },
    "company_name": {
      "type": "string",
      "maxLength": 255,
      "description": "Байгууллагын нэр",
      "example": "TEST LLC"
    },
    "name": {
      "type": "string",
      "maxLength": 255,
      "description": "Бизнесийн нэр (монголоор)",
      "example": "Мерчант12"
    },
    "name_eng": {
      "type": "string",
      "maxLength": 255,
      "description": "Бизнесийн нэр (англиар)",
      "example": "MERCHANT12"
    },
    "mcc_code": {
      "type": "string",
      "maxLength": 255,
      "description": "MCC код. Боломжит кодуудыг `mcc_code` sheet-ээс харна уу.",
      "example": "5311"
    },
    "city": {
      "type": "string",
      "maxLength": 255,
      "description": "Хот/аймгийн код. `/v2/aimaghot`-аас авна.",
      "example": "11000"
    },
    "district": {
      "type": "string",
      "maxLength": 255,
      "description": "Сум/дүүргийн код. `/v2/sumduureg/:city_code`-аас авна.",
      "example": "13000"
    },
    "address": {
      "type": "string",
      "maxLength": 255,
      "description": "Дэлгэрэнгүй хаяг",
      "example": "6 хороо 14-10"
    },
    "phone": {
      "type": "string",
      "maxLength": 255,
      "description": "Утасны дугаар",
      "example": "99112210"
    },
    "email": {
      "type": "string",
      "maxLength": 255,
      "description": "И-мэйл хаяг",
      "example": "admin@gmail.com"
    },
    "location_lat": {
      "type": "string",
      "maxLength": 255,
      "description": "GPS байршлын өргөрөг"
    },
    "location_lng": {
      "type": "string",
      "maxLength": 255,
      "description": "GPS байршлын уртраг"
    },
    "max_qr_account_count": {
      "type": "number",
      "description": "Нэг мерчантад зөвшөөрөгдөх QR дансны дээд тоо"
    }
  }
}

